/* @socom-skeleton stub GetWeaponState__10CZSealBodyCFv */
WEAPON_STATE CZSealBody::GetWeaponState() const
{
	/* 0x2c0670: m_weapon_state without bit 4, as a byte */
	return (WEAPON_STATE)(u8)(m_weapon_state & ~0x10u);
}

/* @socom-skeleton stub WepWaitOff__10CZSealBodyFv */
void CZSealBody::WepWaitOff()
{
	/* 0x2c0650: no raise/wait/lower timing (throwables) */
	m_wep_upT = 0.0f;
	m_wep_waitT = 0.0f;
	m_wep_downT = 0.0f;
	m_wep_sumT = 0.0f;
}

/* @socom-skeleton stub WepWaitOn__10CZSealBodyFv */
void CZSealBody::WepWaitOn()
{
	/* 0x2c0620: the weapon raise/wait/lower timing (the wait practically forever) */
	m_wep_upT = 0.1f;
	m_wep_waitT = 100000.0f;
	m_wep_downT = 0.5f;
	m_wep_sumT = 100000.6f;
}

/* @socom-skeleton stub SetWeaponState__10CZSealBodyF12WEAPON_STATE */
void CZSealBody::SetWeaponState(WEAPON_STATE state)
{
	/* 0x2c0490: a new state (bit 4 = in transition): 2 lowers (the fire sequence restarts
	 * its lowering from the current weight, at most 0.99, of m_wep_downT), 1 raises (from
	 * rest starts the up/wait/down sequence unless the item is binoculars; already within
	 * the hold just drops the transition bit). The remaining time is measured from the
	 * sequence's end. */
	u32 s = (u8)state;

	if (s == (m_weapon_state & ~0x10u))
		return;

	f32 t = m_fire->m_currT;

	if (t > 0.0f)
		t = m_wep_sumT - t;

	if (s == 2)
	{
		f32 w = m_fire->LinearWeight() > 0.99f ? 0.99f : m_fire->LinearWeight();
		m_fire->m_currT = w * m_wep_downT;
		m_weapon_state = 0x12;
	}
	else if (s == 1)
	{
		m_weapon_state = 0x11;

		if (t == 0.0f)
		{
			if (m_kit.GetCurItem() != NULL && m_kit.GetCurItem()->m_ID != EQUIP_ITEM::BINOCULARS)
				m_fire->Start(m_wep_upT, m_wep_waitT, m_wep_downT);
		}
		else if (m_wep_upT <= t && t < m_wep_upT + m_wep_waitT)
		{
			m_weapon_state &= ~0x10u;
		}
	}
}

/* @socom-skeleton stub WeaponsTick__10CZSealBodyFf */
void CZSealBody::WeaponsTick(float dT)
{
	/* 0x2c02c0 (PreTick): the weapon raise/lower transition on the fire sequence; settled
	 * states follow the sequence (raised once it has weight, lowered once it dropped below
	 * full). Then the aim direction, the weapon's aim and the kit's pre-tick (model and
	 * weapon changes). A pure transition flag (0x10) stops here. */
	u32 state = m_weapon_state;

	if ((state & 0x10) == 0)
	{
		if ((state & 0xef) == 2)
		{
			if (m_fire->Weight() != 0.0f)
			{
				m_weapon_state = 1;
				SetWeaponState((WEAPON_STATE)2);
			}
		}
		else if ((state & 0xef) == 1)
		{
			if (m_fire->Weight() != 1.0f)
			{
				m_weapon_state = 2;
				SetWeaponState((WEAPON_STATE)1);
			}
		}
	}
	else
	{
		state &= 0xef;

		if (state == 2)
		{
			m_fire->Tick(dT);

			if (m_fire->m_currT <= 0.0f)
			{
				m_weapon_state &= ~0x10u;
				m_fire->Clear();
			}
		}
		else if (state == 1)
		{
			f32 hold = m_wep_downT + m_wep_waitT;

			if (m_fire->m_currT <= hold)
			{
				m_fire->m_currT = hold;
				m_weapon_state &= ~0x10u;
			}
			else
			{
				m_fire->Tick(dT);
			}
		}
		else if (state != 4 && state == 0x10)
		{
			return;
		}
	}

	UpdateAimDir(false);
	AimWeapon();
	m_kit.PreTick(dT);
}

/* @socom-skeleton stub GetFirepointPos__10CZSealBodyFR6CPnt3DPCc */
bool CZSealBody::GetFirepointPos(CPnt3D &pos, const char *name)
{
	/* 0x2c0140: the current weapon part's named child (its origin; the part origin without
	   a name or such a child) in world space; false without a weapon part or its node */
	SEAL_ITEM item = m_kit.GetCurItemType();
	bool found = false;
	CPnt3D local;

	if (m_weapons[(s8)item] != NULL)
	{
		CZBodyPart *part = BodyWepPart(this, (SEAL_ITEM)(u8)item);
		found = part != NULL && part->m_node != NULL;

		if (found)
		{
			const CPnt3D *offset = NULL;

			if (name != NULL)
			{
				zdb::CNode *child = part->m_node->FindChild(name, false);

				if (child != NULL)
					offset = reinterpret_cast<const CPnt3D *>(&child->m_matrix.m_matrix[3][0]);
			}

			PartInSpace(part, offset, &local, NULL);
		}
	}

	if (found)
		m_node->m_matrix.Transform(&local, &pos, 1);

	return found;
}

/* @socom-skeleton stub GetFirepointNode__10CZSealBodyFPCc */
zdb::CNode * CZSealBody::GetFirepointNode(const char *name)
{
	/* 0x2c00a0: the current weapon part's node, or its named child (none: the node) */
	SEAL_ITEM item = m_kit.GetCurItemType();

	if (m_weapons[(s8)item] == NULL)
		return NULL;

	CZBodyPart *part = BodyWepPart(this, (SEAL_ITEM)(u8)item);

	if (part == NULL)
		return NULL;

	if (name == NULL || part->m_node == NULL)
		return part->m_node;

	return part->m_node->FindChild(name, false);
}

/* @socom-skeleton stub GetNodePos__10CZSealBodyFPCQ23zdb5CNodeR6CPnt3Db */
bool CZSealBody::GetNodePos(const zdb::CNode *node, CPnt3D &out, bool translate)
{
	/* 0x2bfed0: node's position (a child of the current item's weapon part) through the
	 * weapon part chain, then the entity matrix (its translation only when translate);
	 * false without a node, a weapon or its part */
	if (node == NULL)
		return false;

	SEAL_ITEM item = m_kit.GetCurItemType();

	if (m_weapons[(s8)item] == NULL)
		return false;

	CZBodyPart *part = BodyWepPart(this, item);

	if (part == NULL || part->m_node == NULL)
		return false;

	CPnt3D local;
	CPnt3D pos(node->m_matrix.m_matrix[3][0], node->m_matrix.m_matrix[3][1], node->m_matrix.m_matrix[3][2]);
	PartInSpace(part, &pos, &local, NULL);
	const sceVu0FMATRIX &m = m_node->m_matrix.m_matrix;
	out.x = local.x * m[0][0] + local.y * m[1][0] + local.z * m[2][0];
	out.y = local.x * m[0][1] + local.y * m[1][1] + local.z * m[2][1];
	out.z = local.x * m[0][2] + local.y * m[1][2] + local.z * m[2][2];

	if (translate)
	{
		out.x += m[3][0];
		out.y += m[3][1];
		out.z += m[3][2];
	}

	return true;
}

/* @socom-skeleton stub SetAimDirR__10CZSealBodyFPC6CPnt3Db */
unsigned char CZSealBody::SetAimDirR(const CPnt3D *dir, bool reset)
{
	/* 0x2bfe60: the aim goal toward dir (relative); an unattainable dir with reset aims
	 * straight ahead */
	unsigned char result = CalcAimGoal(&m_aim_dir, dir, &m_aim_goal);

	if (!result && reset)
		m_aim_goal = CPnt3D::unit_nz;

	return result;
}

/* @socom-skeleton stub CalcAimGoal__10CZSealBodyFPC6CPnt3DPC6CPnt3DP6CPnt3D */
unsigned char CZSealBody::CalcAimGoal(const CPnt3D *curr, const CPnt3D *dir, CPnt3D *out)
{
	/* 0x2bfba0: in the stand, crouch, in-air and prone states (a peek counts as its base
	 * state) a dir inside the aim cone (the prone limits when prone) is the goal; outside
	 * it CalcGoalDir clamps it. Other states cannot aim. */
	SEAL_STATE state = (SEAL_STATE)m_state;

	if (state == SEAL_STATE::statePeek)
		state = PeekBaseState();

	bool prone = state == SEAL_STATE::stateProne;

	if (!prone && state != SEAL_STATE::stateInAir && state != SEAL_STATE::stateCrouch && state != SEAL_STATE::stateStand)
	{
		m_aimpt_attainable = false;
		return 0;
	}

	f32 cosmin = prone ? theCharacterDynamics.m_cosProneMinAimPitch : theCharacterDynamics.m_cosMinAimPitch;
	f32 cosmax = prone ? theCharacterDynamics.m_cosProneMaxAimPitch : theCharacterDynamics.m_cosMaxAimPitch;
	f32 cosyaw = prone ? theCharacterDynamics.m_cosProneMaxAimYaw : theCharacterDynamics.m_cosMaxAimYaw;
	bool inside = true;
	f32 len = sqrtf(dir->x * dir->x + dir->z * dir->z);
	f32 yawcos = len != 0.0f ? -dir->z / len : 1.0f;

	if (dir->z >= 0.0f)
	{
		if (len < cosmax)
			inside = false;
	}
	else if (len < cosmin)
	{
		inside = false;
	}

	if (yawcos < cosyaw)
		inside = false;

	if (inside)
	{
		*out = *dir;
		m_aimpt_attainable = true;
		return 1;
	}

	f32 minpitch = prone ? theCharacterDynamics.m_proneMinAimPitch : theCharacterDynamics.m_minAimPitch;
	f32 maxpitch = prone ? theCharacterDynamics.m_proneMaxAimPitch : theCharacterDynamics.m_maxAimPitch;
	f32 maxyaw = prone ? theCharacterDynamics.m_proneMaxAimYaw : theCharacterDynamics.m_maxAimYaw;
	unsigned char result = CalcGoalDir(curr, dir, out, maxpitch, minpitch, -maxyaw, maxyaw);
	m_aimpt_attainable = result;
	return result;
}

/* @socom-skeleton stub SetAimPointW__10CZSealBodyFPC6CPnt3DPC6CPnt3Db */
unsigned char CZSealBody::SetAimPointW(const CPnt3D *point, const CPnt3D *norm, bool keep_reticle)
{
	/* 0x2bfa80: the world aim point (and the reticle point too, unless keep_reticle: a
	   blocked shot keeps the reticle where the player looks) and its normal, then the aim
	   direction (UpdateAimDir); without a point, no aim point and the aim straight ahead.
	   Returns UpdateAimDir's result (0 without a point): CSealCtrlAi::FireWhenReady
	   0x262608 uses it */
	if (point == NULL)
	{
		m_have_aim_norm = 0;
		m_aim_point_valid = 0;
		CalcAimGoal(&m_aim_dir, &CPnt3D::unit_nz, &m_aim_goal);
		return 0;
	}

	m_aim_point = *point;
	m_aim_point_valid = 1;

	if (!keep_reticle)
		m_reticle_pt = *point;

	if (norm != NULL)
	{
		m_aim_norm = *norm;
		m_have_aim_norm = 1;
	}
	else
	{
		m_have_aim_norm = 0;
	}

	return UpdateAimDir(keep_reticle);
}

/* @socom-skeleton stub UpdateAimParams__10CZSealBodyFv */
void CZSealBody::UpdateAimParams()
{
	/* 0x2bf920: the current weapon part's "aimpoint" and "firepoint" nodes (found once),
	 * then their positions in the entity's frame (no translation) */
	if (m_curr_aimpt == NULL)
	{
		SEAL_ITEM item = m_kit.GetCurItemType();
		CZBodyPart *part = m_weapons[(s8)item] != NULL ? BodyWepPart(this, item) : NULL;

		if (part == NULL || part->m_node == NULL)
			m_curr_aimpt = NULL;
		else
			m_curr_aimpt = part->m_node->FindChild("aimpoint", false);
	}

	if (m_curr_firept == NULL)
	{
		SEAL_ITEM item = m_kit.GetCurItemType();
		CZBodyPart *part = m_weapons[(s8)item] != NULL ? BodyWepPart(this, item) : NULL;

		if (part == NULL || part->m_node == NULL)
			m_curr_firept = NULL;
		else
			m_curr_firept = part->m_node->FindChild("firepoint", false);
	}

	GetNodePos(m_curr_aimpt, m_curr_aimpos, false);
	GetNodePos(m_curr_firept, m_curr_firepos, false);
}

/* @socom-skeleton stub GetAP__10CZSealBodyFR6CPnt3D */
bool CZSealBody::GetAP(CPnt3D &pos)
{
	/* 0x2bf8a0: the weapon's aim point in world space (the cached "aimpoint" node's
	   position plus the body's, else looked up by name) */
	if (m_curr_aimpt == NULL)
		return GetFirepointPos(pos, "aimpoint");

	pos = m_curr_aimpos;
	pos.Add(GetPosW(), &pos);
	return true;
}

